return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'bel','project-id-version'=>'Babilim 2.2.2','pot-creation-date'=>'2026-11-09T07:54:03+00:00','po-revision-date'=>'2026-11-09T07:54:03+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Адпраўляецца, калі вы націскаеце «Уключыць Babilim», і паўторна, калі сайт трэба зарэгістраваць нанова: URL вашага сайта, версіі WordPress, PHP і Babilim, мова вашага сайта і мовы, якія выкарыстоўваюцца на ім, а таксама публічны ключ, створаны для гэтага сайта.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Адпраўляецца пры кожнай праверцы: спіс усталяваных плагінаў і тэм са станам любога перакладу Babilim, усталяванага для іх, мовы, якія выкарыстоўваюцца, і кароткія дыягнастычныя коды.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Кожны запыт змяшчае URL вашага сайта, а токен доступу сайта дадаецца заўсёды, калі ён патрэбны сервісу.','What Babilim sends to the service'=>'Што Babilim адпраўляе сервісу','Your site\'s URL'=>'URL вашага сайта','WordPress version'=>'Версія WordPress','PHP version'=>'Версія PHP','Babilim version'=>'Версія Babilim','Your site\'s language'=>'Мова вашага сайта','Languages in use on your site'=>'Мовы, якія выкарыстоўваюцца на вашym сайце','A public key for this site'=>'Публічны ключ для гэтага сайта','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Публічны ключ, створаны для гэтага сайта і які выкарыстоўваецца, каб даказаць, што запыты сапраўды паходзяць з гэтага сайта. Адпраўляецца толькі публічная частка; прыватная застаецца на вашым сайце.','Installed plugins and themes'=>'Усталяваныя плагіны і тэмы','Source files (only if you confirm an upload)'=>'Зыходныя файлы (толькі калі вы пацвердзіце загрузку)','Diagnostic codes'=>'Дыягнастычныя коды','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Да 20 кароткіх дыягнастычных кодаў (напрыклад, файл перакладу, які не прайшоў праверку), кожны з плагінам або тэмай, мовай і часам, калі гэта адбылося. Яны ніколі не ўтрымліваюць ніякага тэксту з вашага сайта або перакладзенага тэксту.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d сайт у гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтага сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасць, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim гэтага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?' . "\0" . '%1$d сайты ў гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтых сайтаў, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?' . "\0" . '%1$d сайтаў у гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтых сайтаў, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nothing to do.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Выберыце мову.','%d failed'=>'з памылкай: %d' . "\0" . 'з памылкай: %d' . "\0" . 'з памылкай: %d','%d not yet tried'=>'яшчэ не спрабавана: %d' . "\0" . 'яшчэ не спрабавана: %d' . "\0" . 'яшчэ не спрабавана: %d','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'Чакае %d справаздача. «Заўсёды абагульваць» і «Не абагульваць» адносяцца да ўсіх з іх.' . "\0" . 'Чакаюць %d справаздачы. «Заўсёды абагульваць» і «Не абагульваць» адносяцца да ўсіх з іх.' . "\0" . 'Чакаюць %d справаздач. «Заўсёды абагульваць» і «Не абагульваць» адносяцца да ўсіх з іх.','%d skipped'=>'прапушчана: %d' . "\0" . 'прапушчана: %d' . "\0" . 'прапушчана: %d','%d succeeded'=>'паспяхова: %d' . "\0" . 'паспяхова: %d' . "\0" . 'паспяхова: %d','%d to install'=>'%d для ўсталявання' . "\0" . '%d для ўсталявання' . "\0" . '%d для ўсталявання','(a public key generated for this site)'=>'(публічны ключ, створаны для гэтага сайта)','(detected)'=>'(выяўлена)','(generic codes and coordinates only)'=>'(толькі агульныя коды і каардынаты)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Ачыстка была прыпынена %1$s: %2$s. Нічога не было выдалена.','A file in the component could not be read, so it was not packaged.'=>'Файл у кампаненце не ўдалося прачытаць, таму ён не быў запакаваны.','A host that serves only one PHP request at a time cannot complete this step.'=>'Хостынг, які апрацоўвае толькі адзін запыт PHP за раз, не можа выканаць гэты крок.','A part of the upload kept failing, so the upload was cancelled.'=>'Адна з частак загрузкі пастаянна завяршалася памылкай, таму загрузку скасавана.','A translation cannot be requested for that locale on this site right now.'=>'Зараз запытаць пераклад для гэтай лакалі на гэтым сайце немагчыма.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Запіс у індэкс перакладаў канфліктаваў з іншым запытам %1$s (%2$s) і не быў ужыты; захавана апошняя версія.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Запіс у індэкс перакладаў %1$s (%2$s) не ўдалося завяршыць, і ён не быў ужыты (%3$s).','Account'=>'Уліковы запіс','Add another language'=>'Дадаць яшчэ адну мову','Advanced'=>'Дадатковыя','All'=>'Усе','All free-plan slots for this site are used'=>'Усе слоты бясплатнага плана для гэтага сайта выкарыстаны','All languages'=>'Усе мовы','Already in WordPress core'=>'Ужо ў ядры WordPress','Already installed.'=>'Ужо ўсталявана.','Always share'=>'Заўсёды абагульваць','Another installation is running; try again in a moment.'=>'Выконваецца іншая ўсталёўка; паўтарыце спробу праз момант.','Automatic installs'=>'Аўтаматычныя ўсталёўкі','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Аўтаматычныя ўсталёўкі зараз выключаны; уключыце іх зноў у Налады, калі трэба.','Available'=>'Даступныя','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Даступныя пераклады можна ўсталяваць адным клікам, а адсутныя — запытаць. Пакуль уключаны аўтаматычныя ўсталёўкі, пераклады, якія сэрвіс пазначае як даступныя для вашых моў, усталёўваюцца падчас сінхранізацыі двойчы на дзень.','Available · %s'=>'Даступна · %s','Babilim'=>'Babilim','Babilim adds translations for every language checked here.'=>'Babilim дадае пераклады для кожнай мовы, адзначанай тут.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim не здолеў пацвердзіць часовую папку па-за межамі сайта, таму кампанент не быў запакаваны і нічога не было загружана. Вызначце BABILIM_TEMP_DIR у wp-config.php як папку з правам запісу па-за каранёвай папкай сайта (напрыклад, папку побач з публічным каталогам вашага сайта, а не ўнутры яго) або папрасіце яе ў вашага хостынг-правайдара.','Babilim could not finish checking this site.'=>'Babilim не здолеў завяршыць праверку гэтага сайта.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim не здолеў завяршыць уключэнне (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim не здолеў завяршыць праверку гэтага сайта (сервіс не змог звязацца з ім у адказ). Рэгістрацыя прыпынена.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim не здолеў праверыць гэты сайт, таму нічога не будзе спампавана або ўсталявана, пакуль праверка не завершыцца паспяхова.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim не здолеў праверыць гэты сайт, таму нічога не спампоўваецца і не ўсталёўваецца.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim атрымлівае пераклады з сэрвісу Babilim для плагінаў і тэм на гэтым сайце, якія не маюць перакладу на вашу мову, і ўсталёўвае тыя, што ахоплены вашым тарыфным планам сэрвісу.','Babilim has not been enabled for this site yet.'=>'Babilim для гэтага сайта яшчэ не ўключаны.','Babilim has not installed any translation for this language.'=>'Babilim не ўсталяваў ніводнага перакладу для гэтай мовы.','Babilim hit an error. Share an error report?'=>'У Babilim узнікла памылка. Абагуліць справаздачу пра памылку?','Babilim installed %d translation automatically since your last visit.'=>'Babilim аўтаматычна ўсталяваў %d пераклад пасля вашага апошняга наведвання.' . "\0" . 'Babilim аўтаматычна ўсталяваў %d пераклады пасля вашага апошняга наведвання.' . "\0" . 'Babilim аўтаматычна ўсталяваў %d перакладаў пасля вашага апошняга наведвання.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim выключаны. Больш нічога не адпраўляецца; ужо ўсталяваныя пераклады працягваюць працаваць.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim уключаны: сайт правераны, знойдзены %d кампанент.' . "\0" . 'Babilim уключаны: сайт правераны, знойдзена %d кампаненты.' . "\0" . 'Babilim уключаны: сайт правераны, знойдзена %d кампанентаў.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim уключае і правярае гэты сайт… (апошняя спроба: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim уключае і правярае гэты сайт… Абнавіце старонку або дачакайцеся завяршэння запланаванай праверкі.','Babilim is not enabled.'=>'Babilim не ўключаны.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim наладжаны так, каб сцерці ідэнтычнасць гэтага сайта пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтага сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s. Каб захаваць ідэнтычнасць, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim не паспеў выканаць гэты крок і працягне пры наступнай праверцы.','Babilim settings'=>'Налады Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Сінхранізацыя Babilim часова затрымана сэрвісам (абмежаванне частаты); яна паспрабуе яшчэ раз пасля %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim быў абноўлены, пакуль гэта загрузка чакала. Стары пакет адкінуты; калі ласка, пацвердзіце загрузку яшчэ раз.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim загрузіць гэтыя файлы з %1$s (версія %2$s): кожны файл .php і .js, кожны файл block.json, а таксама readme.txt, readme.md, style.css і theme.json у яго асноўнай папцы. Яны выкарыстоўваюцца для пошуку тэксту, які патрэбна перакласці, і для ідэнтыфікацыі плагіна або тэмы.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest недаступны: %s','Back'=>'Назад','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Раней купілі ліцэнзію для гэтага дамена? Увядзіце код аднаўлення, атрыманы пры афармленні заказу.','Broken placeholder'=>'Пашкоджаны запаўняльнік','Build'=>'Зборка','Built'=>'Створана','Bulk actions apply only to the selected language of each selected component.'=>'Масавыя дзеянні ўжываюцца толькі да абранай мовы кожнага абранага кампанента.','Bulk actions apply to every matching language of each selected component.'=>'Масавыя дзеянні ўжываюцца да кожнай адпаведнай мовы кожнага абранага кампанента.','Bulk download:'=>'Масавае спампоўванне:','Bulk request:'=>'Масавы запыт:','Bulk update:'=>'Масавае абнаўленне:','Bundled with the plugin'=>'Пастаўляецца разам з плагінам','Bundled with the theme'=>'Пастаўляецца разам з тэмай','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Націскаючы «Уключыць», вы згаджаецеся адправіць пералічаныя вышэй звесткі ў Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Працягваючы, вы пацвярджаеце, што маеце права загрузіць гэты кампанент.','Cancel'=>'Скасаваць','Category'=>'Катэгорыя','Check again'=>'Праверыць зноў','Check again now'=>'Праверыць яшчэ раз зараз','Checkout is not available for this site right now.'=>'Афармленне заказу для гэтага сайта цяпер недаступнае.','Choose'=>'Выбраць','Choose a category…'=>'Выберыце катэгорыю…','Choose a language'=>'Выберыце мову','Choose a language…'=>'Выберыце мову…','Clear filters'=>'Ачысціць фільтры','Close'=>'Закрыць','Component'=>'Кампанент','Confirm'=>'Пацвердзіць','Conflicting keys'=>'Канфліктуючыя ключы','Continue'=>'Працягнуць','Continue next batch (%d left)'=>'Працягнуць наступную партыю (засталося: %d)','Continuing…'=>'Працягваем…','Could not back up %s before replacing it.'=>'Не атрымалася стварыць рэзервовую копію %s перад заменай.','Could not create the package archive.'=>'Не атрымалася стварыць архіў пакета.','Could not determine active components; the existing merged index was left unchanged.'=>'Не атрымалася вызначыць актыўныя кампаненты; існуючы аб’яднаны індэкс не зменены.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Не ўдалося вызначыць усталяваныя плагіны/тэмы; ачыстка прапушчана, нічога не выдалена.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Не ўдалося загрузіць поўны спіс лакаляў WordPress.org з сервісу, таму цяпер нельга дадаць іншую мову.','Could not move %s into place.'=>'Не атрымалася перамясціць %s на месца.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Не ўдалося перанесці аб\'яднаны індэкс для \'%s\' на месца; папярэдні індэкс (калі быў) выдалены, каб не заставацца напалову абноўленым. Дапаўненне да дамена па змаўчанні для гэтай лакалі не выдаецца да наступнай паспяховай пабудовы.','Could not open zip: %s'=>'Не атрымалася адкрыць zip: %s','Could not prepare %s for rollback.'=>'Не атрымалася падрыхтаваць %s для адкату.','Could not read %s back after moving it into place.'=>'Не атрымалася прачытаць %s пасля перамяшчэння на месца.','Could not read: %s'=>'Не атрымалася прачытаць: %s','Could not restore the purchase: %s'=>'Не ўдалося аднавіць пакупку: %s','Could not show a new restore code: %s'=>'Не ўдалося паказаць новы код аднаўлення: %s','Could not stage %s'=>'Не атрымалася падрыхтаваць %s','Could not stage default/%s'=>'Не атрымалася падрыхтаваць default/%s','Could not start checkout: %s'=>'Не атрымалася пачаць афармленне заказу: %s','Could not verify entry count for %s'=>'Не атрымалася праверыць колькасць запісаў для %s','Could not write the downloaded package to disk.'=>'Не атрымалася запісаць спампаваны пакет на дыск.','Could not write the staged merged index.'=>'Не ўдалося запісаць падрыхтаваны аб\'яднаны індэкс.','Current translation'=>'Бягучы пераклад','Danger zone'=>'Небяспечная зона','Default supplement entry count mismatch.'=>'Неадпаведнасць колькасці запісаў дапаўнення па змаўчанні.','Delete all Babilim data on uninstall'=>'Выдаліць усе даныя Babilim пры выдаленні','Disable Babilim'=>'Выключыць Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Выключыць Babilim? Усталяваныя пераклады захоўваюцца, але далейшыя праверкі і загрузкі не будуць выконвацца.','Don\'t share'=>'Не абагульваць','Download'=>'Спампаваць','Downloaded and installed.'=>'Спампавана і ўсталявана.','Downloading…'=>'Спампоўванне…','Downloads: %1$d/%2$d (%3$s)'=>'Загрузкі: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Уласны ўклад кожнага кампанента ў агульнае дапаўненне да дамена па змаўчанні для кожнай лакалі.','Enable Babilim'=>'Уключыць Babilim','Enabling…'=>'Уключэнне…','English (United States)'=>'Англійская (Злучаныя Штаты)','Entries'=>'Запісы','Entry count mismatch for %s'=>'Неадпаведнасць колькасці запісаў для %s','Error reports'=>'Справаздачы пра памылкі','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Кожная лакаль, што выкарыстоўваецца на гэтым сайце (лакаль сайта, усталяваныя моўныя пакеты, лакалі карыстальнікаў і любыя, што вы дадасце ўручную). Ніводная лакаль не разглядаецца інакш за іншую.','Excluded'=>'Выключана','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Файлы з іншымі назвамі або пашырэннямі не ўключаюцца, як і папкі uploads, cache, logs, backup, data, vendor, node_modules і languages, схаваныя файлы і файлы, назвы якіх адпавядаюць распаўсюджаным сакрэтам (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Файлы з кодам усё роўна могуць змяшчаць тэкст або даныя, якімі вы не хацелі б дзяліцца; праверце іх, калі сумняваецеся. Сэрвіс паўторна выдаляе такія ж віды файлаў пры атрыманні.','Free'=>'Бясплатна','Free-plan slots'=>'Слоты бясплатнага плана','General'=>'Агульныя','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Калі гэта ўключана, пры выдаленні таксама будзе сцерта ідэнтычнасць гэтага сайта. Платную ліцэнзію, прывязаную да гэтага сайта, пасля гэтага нельга будзе аднавіць аўтаматычна; каб вярнуць яе, трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s.','Included'=>'Уключана','Included in index'=>'Уключана ў індэкс','Install available translations automatically'=>'Аўтаматычна ўсталёўваць даступныя пераклады','Installed'=>'Усталяваныя','Installed translations are kept, but no further checks or downloads will run.'=>'Усталяваныя пераклады захоўваюцца, але далейшыя праверкі і спампоўванні выконвацца не будуць.','Installed · %s'=>'Усталявана · %s','Installed · built for %1$s, this site has %2$s'=>'Усталявана · створана для %1$s, на гэтым сайце %2$s','Installed · built for %s'=>'Усталявана · створана для %s','Installed · built for %s, new version failed'=>'Усталявана · створана для %s, збой пры падрыхтоўцы новай версіі','Installed · built for %s, new version scheduled'=>'Усталявана · створана для %s, новая версія запланавана','Installed · built for %s, translating the new version…'=>'Усталявана · створана для %s, перакладаецца новая версія…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Усталявана · створана для %s; гэты плагін або тэма больш не ўваходзіць у тарыфны план сайта','Installed · built for a different version'=>'Усталявана · створана для іншай версіі','Installed · built for a different version, new version failed'=>'Усталявана · створана для іншай версіі, збой пры падрыхтоўцы новай версіі','Installed · built for a different version, new version scheduled'=>'Усталявана · створана для іншай версіі, новая версія запланавана','Installed · built for a different version, translating the new version…'=>'Усталявана · створана для іншай версіі, перакладаецца новая версія…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Усталявана · створана для іншай версіі; гэты плагін або тэма больш не ўваходзіць у тарыфны план сайта','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Яны захоўваюцца хостынг-правайдарам сервіса і апрацоўваюцца мадэлямі ШІ для стварэння перакладу.','Language'=>'Мова','Language:'=>'Мова:','Languages'=>'Мовы','Languages found on this site: %s.'=>'Мовы, знойдзеныя на гэтым сайце: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Апошняя ачыстка %1$s: %2$d нядаўна пазначана, %3$d файл(аў) выдалена, %4$d запіс(аў) выдалена.','Maintenance'=>'Абслугоўванне','Maintenance status is not available right now.'=>'Стан абслугоўвання цяпер недаступны.','Manifest unavailable: %s'=>'Маніфест недаступны: %s','Negation reversed'=>'Адмаўленне перайначана','No'=>'Не','No build is available to download for this locale.'=>'Для гэтай лакалі няма зборкі, даступнай для спампоўвання.','No cleanup has run yet.'=>'Ачыстка яшчэ не выконвалася.','No components match these filters. %s'=>'Ніводны кампанент не адпавядае гэтым фільтрам. %s','No components synced yet.'=>'Кампаненты яшчэ не сінхранізаваны.','No installed translation matches.'=>'Адпаведных усталяваных перакладаў не знойдзена.','No language is managed yet.'=>'Ніводная мова яшчэ не кіруецца.','No pending challenge for this nonce.'=>'Для гэтага nonce няма выклікаў у чаканні.','No pending challenge to verify.'=>'Няма чакаючага выкліку для праверкі.','No plugins or themes found.'=>'Убудовы або тэмы не знойдзены.','No previous build to roll back to.'=>'Няма папярэдняй зборкі для адкату.','No record for %s'=>'Няма запісу для %s','No site id is on file to rotate a token for.'=>'У файле няма захаванага ідэнтыфікатара сайта, для якога можна змяніць токен.','No — component inactive'=>'Не — кампанент неактыўны','No — component removed'=>'Не — кампанент выдалены','No — installed version differs from the active one'=>'Не — усталяваная версія адрозніваецца ад актыўнай','Not a valid server_build_id: %s'=>'Недапушчальны server_build_id: %s','Not covered by the free service plan'=>'Не ахоплена бясплатным планам сэрвісу','Not installed'=>'Не ўсталявана','Not registered yet'=>'Яшчэ не зарэгістравана','Not supported'=>'Не падтрымліваецца','Not verified'=>'Не правераны','Note (optional)'=>'Заўвага (неабавязкова)','Nothing to choose.'=>'Няма з чаго выбіраць.','Nothing to confirm.'=>'Няма чаго пацвярджаць.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Па змаўчанні выключана: пры выдаленні плагіна ідэнтычнасць гэтага сайта захоўваецца, каб яе можна было паўторна выкарыстаць пры пераўсталёўцы.','One or more served files no longer match the manifest.'=>'Адзін або некалькі файлаў, што выдаюцца, больш не адпавядаюць маніфесту.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Аднаразовая пакупка для гэтага сайта: %1$s %2$s. Уключае ўсе будучыя абнаўленні перакладаў. Аплата апрацоўваецца праз Paddle у новай укладцы.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Гэта можа зрабіць толькі адміністратар сеткі, бо змяняюцца файлы перакладу, агульныя для ўсіх сайтаў гэтай сеткі.','Only plugins and themes can be packaged.'=>'Упакоўваць можна толькі плагіны і тэмы.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Толькі калі вы пацвярджаеце загрузку для плагіна або тэмы, якіх няма на WordPress.org: кожны файл .php і .js, кожны файл block.json, а таксама readme.txt, readme.md, style.css і theme.json у асноўнай папцы гэтага кампанента, у выглядзе zip-архіва, пасля выключэння файлаў, якія адпавядаюць распаўсюджаным сакрэтам.','Open Babilim settings'=>'Адкрыць налады Babilim','Original language'=>'Зыходная мова','Original string'=>'Зыходны радок','Paid'=>'Платны','Partner'=>'Партнёр','Please check that your site can be reached from the internet, then try again.'=>'Праверце, ці даступны ваш сайт з інтэрнэту, і паспрабуйце яшчэ раз.','Please choose a category for this report.'=>'Выберыце катэгорыю для гэтай справаздачы.','Plugin'=>'Плагін','Plugin · %s'=>'Убудова · %s','Plugins'=>'Убудовы','Preview'=>'Папярэдні прагляд','Purchase restored. This site is now licensed.'=>'Пакупка адноўлена. Цяпер гэты сайт мае ліцэнзію.','Re-parsed entry count did not match the built index.'=>'Колькасць запісаў пасля паўторнага разбору не супала з пабудаваным індэксам.','Re-verify'=>'Праверыць паўторна','Rebuild index now'=>'Перабудаваць індэкс зараз','Refusing to write outside the Babilim language-file directory.'=>'Адмова ад запісу па-за каталогам моўных файлаў Babilim.','Registration response was missing required fields.'=>'У адказе на рэгістрацыю адсутнічалі патрэбныя палі.','Registration restarted.'=>'Рэгістрацыю перазапушчана.','Remove'=>'Выдаліць','Remove everything Babilim installed'=>'Выдаліць усё, што ўсталяваў Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Выдаліць усё, што ўсталяваў Babilim? Гэта выдаліць кожны моўны файл, які ён усталяваў для кожнага плагіна і кожнай тэмы на гэтым сайце.','Remove the %2$s translation of %1$s from this site?'=>'Выдаліць з гэтага сайта пераклад %1$s на мову %2$s?','Removed %d installed component.'=>'Выдалены %d усталяваны кампанент.' . "\0" . 'Выдалена %d усталяваныя кампаненты.' . "\0" . 'Выдалена %d усталяваных кампанентаў.','Removed after a failed integrity check'=>'Выдалена пасля няўдалай праверкі цэласнасці','Removed.'=>'Выдалена.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Выдаляе кожны моўны файл, які Babilim усталяваў для кожнага плагіна і кожнай тэмы на гэтым сайце.','Report a problem'=>'Паведаміць пра праблему','Report translation'=>'Паведаміць пра праблему з перакладам','Request newer translation'=>'Запытаць новы пераклад','Request translation'=>'Запытаць пераклад','Requestable'=>'Можна запытаць','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Пры запыце перакладу гэты плагін або тэма займае адзін са слотаў бясплатнага тарыфнага плана паслугі для гэтага сайта (ліміт: %1$d для тэм і %2$d для плагінаў), калі яшчэ не займае слот. Слот застаецца занятым, а няўдалы пераклад яго не вызваляе.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Пры запыце перакладу гэты плагін або тэма займае адзін са слотаў бясплатнага тарыфнага плана паслугі для гэтага сайта, калі яшчэ не займае слот. Слот застаецца занятым, а няўдалы пераклад яго не вызваляе.','Requesting…'=>'Запыт…','Restart registration'=>'Пачаць рэгістрацыю нанова','Restore code'=>'Код аднаўлення','Restore purchase'=>'Аднавіць пакупку','Retry request'=>'Паўтарыць запыт','Roll back'=>'Адкаціць','Roll back and report'=>'Адкаціць і паведаміць','Roll back and send report'=>'Адкаціць і адправіць справаздачу','Roll back the %2$s translation of %1$s to the previous build?'=>'Вярнуць пераклад %2$s для %1$s да папярэдняй зборкі?','Rolled back and reported.'=>'Адкат выкананы, справаздача адпраўлена.','Rolled back to the previous build.'=>'Выканана вяртанне да папярэдняй зборкі.','Rolled back, but the report could not be sent: %s'=>'Адкат выкананы, але справаздачу адправіць не ўдалося: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Адкат перазапісаў бы \'%1$s\' (%2$s), які цяпер выдаецца для іншага ўсталяванага кампанента (%3$s); нічога не зменена.','Rotate-token response was missing site_token.'=>'У адказе на змену токена адсутнічаў site_token.','Save changes'=>'Захаваць змены','Scheduled, waiting to be processed'=>'Запланавана, чакае апрацоўкі','Search'=>'Шукаць','Search components'=>'Пошук кампанентаў','Search the installed translations'=>'Пошук па ўсталяваных перакладах','Select all'=>'Выбраць усё','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Выберыце менш кампанентаў: не больш за %1$d аперацый за адзін запуск (вы выбралі %2$d).','Send report'=>'Адправіць справаздачу','Service plan'=>'Тарыфны план сэрвісу','Settings'=>'Налады','Share error reports'=>'Абагуліць справаздачы пра памылкі','Share this report'=>'Абагуліць гэтую справаздачу','Show a new restore code'=>'Паказаць новы код аднаўлення','Show the "Report translation" entry in the admin toolbar'=>'Паказваць пункт «Report translation» на панэлі інструментаў адміністравання','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Частка тэксту гэтага кампанента жорстка закадзіравана яго аўтарам і не можа быць перакладзена моўным пакетам.','Status'=>'Стан','Status unknown'=>'Стан невядомы','String context'=>'Кантэкст радка','Suggested translation'=>'Прапанаваны пераклад','Supplementary translation index'=>'Індэкс дадатковых перакладаў','Supplementary translation index rebuilt.'=>'Дадатковы індэкс перакладаў адноўлены.','Supplementary translation maintenance'=>'Абслугоўванне дадатковых перакладаў','Supplementary translations'=>'Дадатковыя пераклады','Sweep aborted without orphaning anything: %s.'=>'Ачыстка спынена без пазначэння асірацелых запісаў: %s.','Sweep complete: %d file deleted.'=>'Ачыстка завершана: выдалены %d файл.' . "\0" . 'Ачыстка завершана: выдалена %d файлы.' . "\0" . 'Ачыстка завершана: выдалена %d файлаў.','Sweep now'=>'Ачысціць зараз','Sync complete.'=>'Сінхранізацыя завершана.','Thank you. Your report was sent.'=>'Дзякуй. Вашу справаздачу адпраўлена.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Гэты кампанент не ўсталяваны на гэтым сайце, таму запытаць для яго пераклад нельга.','That does not look like a restore code.'=>'Гэта не падобна на код аднаўлення.','That is not a valid WordPress locale code. Nothing was saved.'=>'Гэта не сапраўдны код лакалі WordPress. Нічога не захавана.','That is not a valid build identifier.'=>'Гэта не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Гэты экран запампоўкі састарэў: з таго часу была падрыхтавана іншая запампоўка. Нічога не было адпраўлена. Праглядзіце бягучую са Спісу перакладаў.','The change could not be recorded in the translation index; please try again.'=>'Не атрымалася занесці змяненне ў індэкс перакладаў; паспрабуйце яшчэ раз.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Ачыстка выканана, але частку яе змен не ўдалося запісаць у індэкс перакладаў; наступная ачыстка паўторыць спробу.','The component has no files that can be uploaded.'=>'У кампанента няма файлаў, якія можна загрузіць.','The component is not inside the plugins or themes directory.'=>'Кампанент не знаходзіцца ў каталогу плагінаў або тэм.','The component\'s main file was not found.'=>'Асноўны файл кампанента не знойдзены.','The download response was missing a usable location.'=>'У адказе на спампоўванне адсутнічала прыдатная лакацыя.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Гэты пункт адкрывае панэль для пошуку перакладаў, усталяваных Babilim на гэтым сайце, і для паведамлення пра праблему ў адным з іх.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Поле "%1$s" занадта доўгае: у ім %2$d сімвалаў, а ліміт — %3$d. Нічога не адпраўлена; скараціце яго і паспрабуйце яшчэ раз.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Бясплатны тарыфны план паслугі дае кожнаму сайту абмежаваную колькасць слотаў для плагінаў і тэм; выкарыстаныя слоты паказваюцца ў раздзеле «Налады» пасля ўключэння Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Зададзены дамен \'%1$s\' не адпавядае ні ўласнаму slug маніфеста пакета \'%2$s\', ні яго text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Аб’яднаны індэкс для \'%s\' перабудаваны, але індэкс перакладаў не змог яго запісаць; наступная перабудова паўторыць спробу.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Зыходны тэкст і створаныя на яго аснове пераклады будуць перададзены іншым сайтам, якія ўсталююць тую ж версію.','The package declares no main translation file.'=>'Пакет не аб\'яўляе асноўнага файла перакладу.','The package has no %s for its own text domain.'=>'У пакеце няма %s для ўласнага тэкставага дамена.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Тып \'%1$s\' у маніфесце пакета не адпавядае запытанаму тыпу \'%2$s\'.','The package produced no servable main translation file.'=>'Пакет не стварыў прыдатнага для выдачы асноўнага файла перакладу.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Тэкставы дамен пакета \'%1$s\' не адпавядае копіі кампанента на гэтым сайце (\'%2$s\'), таму пакет не ўсталяваны.','The packaged component could not be read.'=>'Не атрымалася прачытаць запакаваны кампанент.','The registration challenge is not in the expected form.'=>'Выклік рэгістрацыі мае неčаканую форму.','The report could not be sent.'=>'Не атрымалася адправіць справаздачу.','The search could not be completed.'=>'Не атрымалася завяршыць пошук.','The service asked this site to wait before syncing again.'=>'Сэрвіс папрасіў гэты сайт пачакаць перад наступнай сінхранізацыяй.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сэрвіс не здолеў звязацца з вашым сайтам. Магчыма, брандмаўэр, плагін бяспекі або правіла хостынгу блакуе запыт; калі ласка, дазвольце запыты да /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Прапанова сэрвісу для загрузкі была няпоўнай.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Тэкставы дамен \'%1$s\' (%2$s) ужо выдаецца для іншага ўсталяванага кампанента (%3$s); нічога не ўсталявана.','The upload is kept until you ask Babilim to delete it.'=>'Запампаваныя даныя захоўваюцца, пакуль вы не папросіце Babilim выдаліць іх.','Theme'=>'Тэма','Theme · %s'=>'Тэма · %s','Themes'=>'Тэмы','There is no upload in progress.'=>'Запампоўка не выконваецца.','There is no upload waiting for confirmation.'=>'Няма запампоўкі, якая чакае пацвярджэння.','These are the languages this site uses. You can change them in %s.'=>'Гэта мовы, якія выкарыстоўвае гэты сайт. Вы можаце змяніць іх у %s.','These fields will be sent:'=>'Будуць адпраўлены наступныя палі:','This build is not one this site currently knows about for this component/locale.'=>'Гэтая зборка не з\'яўляецца той, пра якую гэты сайт зараз ведае для гэтага кампанента і лакалі.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Гэты кампанент не паказвае нумар версіі, таму запытаць для яго пераклад нельга.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Гэты кампанент большы за дапушчальны для сэрвісу памер, таму яго нельга загрузіць.','This component was already uploaded. Babilim is checking it now.'=>'Гэты кампанент ужо быў загружаны. Babilim зараз правярае яго.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Нумар версіі гэтага кампанента даўжэйшы за %d сімвалаў, чаго Babilim апрацаваць не можа, таму запытаць для яго пераклад нельга.','This issues a new restore code and the previous one stops working. Continue?'=>'Будзе выдадзены новы код аднаўлення, а папярэдні перастане працаваць. Працягнуць?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'У гэтай сетцы занадта шмат сайтаў, каб правяраць іх па адным, і некаторыя з іх могуць быць наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да такога сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Версія самога гэтага плагіна, каб сэрвіс мог параіць абнавіць яго, калі яна занадта старая для сувязі.','This report does not name a valid plugin or theme and locale.'=>'У гэтай справаздачы не паказаны сапраўдны плагін або тэма і лакаль.','This report does not name an installed string.'=>'У гэтай справаздачы не названы ўсталяваны радок.','This report is missing a valid build to report against.'=>'У гэтым справаздачы адсутнічае сапраўдная зборка, да якой яна адносіцца.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Гэтая справаздача будзе апублікавана на GitHub і можа быць захавана трэцімі асобамі.','This restore code was not recognised for this site.'=>'Гэты код аднаўлення не распазнаны для гэтага сайта.','This site already has an active registration that can no longer be recovered automatically.'=>'Гэты сайт ужо мае актыўную рэгістрацыю, якую больш нельга аднавіць аўтаматычна.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'На гэтым сайце %1$d кампанентаў на %2$d мовах, што патрабуе %3$d пакетаў праверкі; Babilim можа апрацаваць не больш за %4$d за запуск. Скараціце колькасць кіраваных моў у раздзеле «Налады» або дэактывуйце невыкарыстоўваныя плагіны і тэмы, а потым націсніце «Праверыць яшчэ раз зараз».','This site has no purchase to show a code for.'=>'Для гэтага сайта няма пакупкі, для якой можна паказаць код.','This site is already licensed. Reload the page.'=>'Гэты сайт ужо мае ліцэнзію. Перазагрузіце старонку.','This site is not registered with Babilim yet.'=>'Гэты сайт яшчэ не зарэгістраваны ў Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Гэты сайт перавышае памер, які сэрвіс прымае за адну сінхранізацыю, таму некаторыя элементы прапушчаны: кампанентаў — %1$d, лакалей — %2$d.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Гэты сайт уваходзіць у сетку multisite, якая не ўсталёўвае новыя пераклады аўтаматычна. Ужо ўсталяваныя пераклады па-ранейшаму абнаўляюцца.','This site is verified.'=>'Гэты сайт правераны.','This site must be verified first.'=>'Спачатку гэты сайт трэба пацвердзіць.','This site\'s URL, so the service can verify you own it.'=>'URL гэтага сайта, каб сэрвіс мог пацвердзіць, што ён належыць вам.','This site\'s address is too long for Babilim to register.'=>'Адрас гэтага сайта занадта доўгі для рэгістрацыі ў Babilim.','This site\'s configured locale.'=>'Наладжаная лакаль гэтага сайта.','This site\'s locale code is not one Babilim can register.'=>'Код лакалі гэтага сайта не можа быць зарэгістраваны ў Babilim.','This string can\'t be reported from this site.'=>'Пра гэты радок нельга паведаміць з гэтага сайта.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Гэтага радка няма сярод перакладаў, усталяваных на гэтым сайце. Паўтарыце пошук і абярыце яго са спісу.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Гэты пераклад быў абноўлены пасля вашага пошуку. Паўтарыце пошук і абярыце радок з новага спісу.','To translate this component, Babilim needs its source.'=>'Каб перакласці гэты кампанент, Babilim патрэбна яго крыніца.','Too many attempts. Try again tomorrow.'=>'Занадта шмат спроб. Паспрабуйце зноў заўтра.','Too many reports today. Try again tomorrow.'=>'Сёння занадта шмат справаздач. Паспрабуйце заўтра.','Too many requests.'=>'Занадта шмат запытаў.','Toolbar'=>'Панэль інструментаў','Translating…'=>'Пераклад…','Translation does not load'=>'Пераклад не загружаецца','Translation failed'=>'Не ўдалося перакласці','Translation requested.'=>'Пераклад запрошаны.','Translations'=>'Пераклады','Type'=>'Тып','Type at least 2 characters to search.'=>'Для пошуку ўвядзіце не менш за 2 сімвалы.','Unexpected HTTP %d response.'=>'Нечаканы HTTP-адказ %d.','Uninstall'=>'Выдаленне','Unknown kind: %s'=>'Невядомы тып: %s','Unsafe domain: %s'=>'Небяспечны дамен: %s','Unsafe locale: %s'=>'Небяспечная лакаль: %s','Unsafe slug: %s'=>'Небяспечны slug: %s','Unsafe text_domain: %s'=>'Небяспечны text_domain: %s','Update'=>'Абнавіць','Update available'=>'Даступна абнаўленне','Updates'=>'Абнаўленні','Updating…'=>'Абнаўленне…','Upgrade this site'=>'Палепшыць план гэтага сайта','Upload and request'=>'Запампаваць і даслаць запыт','Upload cancelled.'=>'Загрузка скасавана.','Upload complete — translation requested.'=>'Загрузка завершана — пераклад запрошаны.','Upload expired before it finished'=>'Тэрмін запампоўкі скончыўся да яе завяршэння','Upload in progress — continue or cancel'=>'Запампоўка выконваецца — працягнуць або скасаваць','Upload this component?'=>'Загрузіць гэты кампанент?','Upload was not accepted'=>'Запампоўка не прынята','Uploading'=>'Запампоўка','Uploading part %1$d of %2$d…'=>'Запампоўка часткі %1$d з %2$d…','Uploading…'=>'Запампоўка…','Verified'=>'Пацверджана','Verify response was missing site_token.'=>'У адказе на праверку адсутнічаў site_token.','Version %s'=>'Версія %s','What is sent when you enable Babilim'=>'Што адпраўляецца, калі вы ўключаеце Babilim','Where you saw this (optional)'=>'Дзе вы гэта ўбачылі (неабавязкова)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Пакуль гэта ўключана, пераклады, якія сэрвіс пазначае як даступныя для вашых моў, усталёўваюцца падчас сінхранізацыі двойчы на дзень.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Няправільна для гэтага кантэксту','Wrong meaning'=>'Няправільнае значэнне','Wrong plural form'=>'Няправільная форма множнага ліку','Wrong term'=>'Няправільны тэрмін','Yes'=>'Так','You are not allowed to do this.'=>'Вам не дазволена гэта рабіць.','Your PHP version, for compatibility.'=>'Ваша версія PHP, для праверкі сумяшчальнасці.','Your WordPress version, to serve compatible translation files.'=>'Ваша версія WordPress, каб прадастаўляць сумяшчальныя файлы перакладу.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ваш новы код аднаўлення: %s. Захоўвайце яго ў надзейным месцы — папярэдні код больш не працуе.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Ваша справаздача апрацоўваецца аўтаматычна мадэлямі AI і можа палепшыць гэты пераклад для іншых сайтаў.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ваш сайт адказаў, але не тым, чаго чакалася. Магчыма, REST API перапісваецца іншым плагінам або гэты эндпоінт кэшуецца; калі ласка, выключыце /wp-json/babilim/v1/challenge з кэшавання і перапісвання.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ваш сайт адказваў занадта доўга. Паспрабуйце пазней і праверце, ці не занадта павольны або перагружаны ваш хостынг.','Zip has no manifest.json.'=>'У zip няма manifest.json.','Zip is missing expected default file: %s'=>'У zip-архіве адсутнічае чаканы файл па змаўчанні: %s','Zip is missing expected file: %s'=>'У zip-архіве адсутнічае чаканы файл: %s','_manifest.json has an unexpected structure'=>'_manifest.json мае нечаканую структуру','could not read _manifest.json: %s'=>'не атрымалася прачытаць _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest адсутнічае або мае няслушны параметр \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Параметр \'server_build_id\' у expected_manifest не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','failed to parse _manifest.json: %s'=>'не атрымалася разабраць _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'гэта зробіць асірацелымі %1$d з %2$d кіраваных кампанентаў (больш за палову)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'гэта зробіць асірацелым кожны кіраваны кампанент тыпу %1$s (%2$d з %2$d)','l10n.php entry count mismatch for %s'=>'Неадпаведнасць колькасці запісаў l10n.php для %s','manifest.json has an invalid \'default_domain_entries\'.'=>'У manifest.json няслушны параметр \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'У manifest.json няслушны параметр \'default_domain_files\'.','manifest.json in the zip is not valid JSON.'=>'manifest.json у zip не з\'яўляецца дапушчальным JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'%s\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'build_no\'.','manifest.json is missing or has an invalid \'entries\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'entries\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'extra_domains\'.','manifest.json is missing or has an invalid \'files\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'files\'.','manifest.json\'s \'%s\' does not match the expected value.'=>'Поле \'%s\' у manifest.json не адпавядае чаканаму значэнню.','manifest.json\'s \'contract\' is not a valid version string.'=>'Параметр \'contract\' у manifest.json не з\'яўляецца дапушчальным радком версіі.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Параметр \'kind\' у manifest.json павінен мець значэнне \'plugin\' або \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' у manifest.json не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','manifest.json\'s \'status\' must be \'published\'.'=>'Параметр \'status\' у manifest.json павінен мець значэнне \'published\'.','nonce must be a hexadecimal string.'=>'nonce павінен быць шаснаццатковым радком.','per day'=>'у дзень','rc_…'=>'rc_…','sha256 mismatch for %s'=>'Неадпаведнасць sha256 для %s','sha256 mismatch for default/%s'=>'Неадпаведнасць sha256 для default/%s','component kind in the sweep brake messageplugin'=>'плагін','component kind in the sweep brake messagetheme'=>'тэма','problem report categoryOther'=>'Іншае','translation statusAvailable'=>'Даступна','translation statusInstalled'=>'Усталявана','Babilim translation turned off.'=>'Пераклад Babilim выключаны.','Stop using Babilim translation'=>'Спыніць выкарыстанне перакладу Babilim','Use Babilim translation'=>'Выкарыстоўваць пераклад Babilim','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Спыніць выкарыстанне перакладу Babilim для %1$s (%2$s)? WordPress будзе выкарыстоўваць уласны пераклад тэмы або пераклад WordPress.org. Вы можаце вярнуцца назад у любы час.','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Спыніць выкарыстанне перакладу Babilim для %1$s (%2$s)? WordPress будзе выкарыстоўваць уласны пераклад плагіна або пераклад WordPress.org. Вы можаце вярнуцца назад у любы час.','Enjoying Babilim? Please leave a rating on WordPress.org.'=>'Падабаецца Babilim? Калі ласка, пакіньце ацэнку на WordPress.org.','Rate Babilim'=>'Ацаніць Babilim','Babilim translation bundled with the theme'=>'Пераклад Babilim, убудаваны ў тэму','Babilim translation bundled with the plugin'=>'Пераклад Babilim, убудаваны ў плагін','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, the languages it already includes, and which of those bundled translations Babilim generated (language codes only). For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Для кожнага ўсталяванага плагіна і кожнай тэмы: назва (слаг), версія, text domain, ці пазначаны ён на WordPress.org, якія мовы ўжо ўключаны, і якія з гэтых убудаваных перакладаў стварыў Babilim (толькі коды моў). Для кожнага ўсталяванага перакладу Babilim: якой ён версіі, калі апошні раз правяраўся і ці прайшоў праверку файлаў.','Working…'=>'Апрацоўка…','Babilim could not finish this. Reload the page and try again.'=>'Babilim не здолеў завяршыць гэта. Перазагрузіце старонку і паспрабуйце яшчэ раз.','This translation does not have the number of forms the language needs.'=>'У гэтым перакладзе няма патрэбнай для мовы колькасці формаў.','This translation is empty.'=>'Гэты пераклад пусты.','The text has invalid characters or control characters.'=>'Тэкст змяшчае недапушчальныя або кіравальныя сімвалы.','The HTML tags must match the original: same tags, each opened and closed as in the original.'=>'HTML-тэгі павінны супадаць з арыгіналам: тыя ж тэгі, кожны адкрыты і закрыты так жа, як у арыгінале.','The translation has %s, which the original does not. Keep the placeholders of the original; to write a plain percent sign next to a letter, add a space or write %%%%.'=>'У перакладзе ёсць %s, якога няма ў арыгінале. Захавайце запаўняльнікі арыгінала; каб напісаць звычайны знак працэнта побач з літарай, дадайце прабел або напішыце %%%%.','The translation has a lone percent sign that would break the text. Write 100%% for a literal percent sign.'=>'У перакладзе ёсць асобны знак працэнта, які пашкодзіць тэкст. Напішыце 100%% для літаральнага знака працэнта.','Unsafe override scope.'=>'Небяспечная вобласць перавызначэння.','The override files could not be written.'=>'Не ўдалося запісаць файлы перавызначэння.','That plugin, theme, text domain or language is not available here.'=>'Гэты плагін, тэма, дамен тэксту або мова тут недаступныя.','The editor could not complete that request.'=>'Рэдактар не змог выканаць гэты запыт.','The translation did not pass the checks, so it was not saved. Your text is kept as a draft.'=>'Пераклад не прайшоў праверку, таму не быў захаваны. Ваш тэкст захаваны як чарнавік.','The table that stores edited translations does not exist yet.'=>'Табліца, у якой захоўваюцца адрэдагаваныя пераклады, яшчэ не існуе.','That plugin or theme is not installed.'=>'Гэты плагін або тэма не ўсталяваны.','That string is not in this translation.'=>'Гэтага радка няма ў гэтым перакладзе.','The translation could not be saved.'=>'Не ўдалося захаваць пераклад.','Edit translations'=>'Рэдагаваць пераклады','Edit translations: %1$s, %2$s'=>'Рэдагаваць пераклады: %1$s, %2$s','There is nothing to edit yet. Install a plugin or theme, or add a language, and it shows up here.'=>'Пакуль няма чаго рэдагаваць. Усталюйце плагін або тэму ці дадайце мову, і яны з’явяцца тут.','Choose a plugin or theme and a language to edit its translation.'=>'Абярыце плагін або тэму і мову, каб рэдагаваць яе пераклад.','Name'=>'Назва','Edit'=>'Рэдагаваць','Back to all plugins and themes'=>'Назад да ўсіх плагінаў і тэм','Text domain'=>'Дамен тэксту','Show'=>'Паказаць','The editor needs JavaScript. Everything else in Babilim works without it.'=>'Для рэдактара патрэбны JavaScript. Усё астатняе ў Babilim працуе без яго.','Untranslated'=>'Не перакладзена','Needs review'=>'Патрабуе праверкі','No longer used'=>'Больш не выкарыстоўваецца','From Babilim'=>'Ад Babilim','From WordPress.org'=>'З WordPress.org','From the plugin or theme'=>'Ад плагіна або тэмы','Save'=>'Захаваць','You are logged out. Log in again in another tab, then press Save.'=>'Вы выйшлі з сістэмы. Увайдзіце зноў на іншай укладцы, потым націсніце «Захаваць».','This text is not saved yet. It stays in the field.'=>'Гэты тэкст яшчэ не захаваны. Ён застаецца ў полі.','Form %d'=>'Форма %d','Translation'=>'Пераклад','Original text'=>'Зыходны тэкст','Context'=>'Кантэкст','Note for translators'=>'Заўвага для перакладчыкаў','Previous page'=>'Папярэдняя старонка','Next page'=>'Наступная старонка','Page %1$d of %2$d'=>'Старонка %1$d з %2$d','No more untranslated strings on this page.'=>'На гэтай старонцы больш няма неперакладзеных радкоў.','No strings match.'=>'Адпаведных радкоў няма.','No strings found. This plugin or theme does not ship a translation template.'=>'Радкоў не знойдзена. Гэты плагін або тэма не мае шаблону перакладу.','The translation file could not be written yet. It is tried again automatically every day.'=>'Файл перакладу пакуль не ўдалося запісаць. Спроба паўтараецца аўтаматычна кожны дзень.','Edit this text'=>'Рэдагаваць гэты тэкст','Has problems'=>'Ёсць праблемы','%d string'=>'%d радок' . "\0" . '%d радкі' . "\0" . '%d радкоў','%d untranslated'=>'%d без перакладу' . "\0" . '%d без перакладу' . "\0" . '%d без перакладу','%d edited by you'=>'%d адрэдагавана вамі' . "\0" . '%d адрэдагаваны вамі' . "\0" . '%d адрэдагавана вамі','%d change is live.'=>'%d змяненне апублікавана.' . "\0" . '%d змяненні апублікаваны.' . "\0" . '%d змяненняў апублікавана.','%d change is saved.'=>'%d змяненне захавана.' . "\0" . '%d змяненні захаваны.' . "\0" . '%d змяненняў захавана.','%d draft needs fixing and was not saved.'=>'%d чарнавік патрабуе выпраўлення і не быў захаваны.' . "\0" . '%d чарнавікі патрабуюць выпраўлення і не былі захаваны.' . "\0" . '%d чарнавікоў патрабуюць выпраўлення і не былі захаваны.','%d change could not be saved.'=>'%d змяненне не ўдалося захаваць.' . "\0" . '%d змяненні не ўдалося захаваць.' . "\0" . '%d змяненняў не ўдалося захаваць.','Nothing to save.'=>'Няма чаго захоўваць.','Save %d change'=>'Захаваць %d змяненне' . "\0" . 'Захаваць %d змяненні' . "\0" . 'Захаваць %d змяненняў','%d draft saved, not live yet'=>'%d чарнавік захаваны, пакуль не апублікаваны' . "\0" . '%d чарнавікі захаваны, пакуль не апублікаваны' . "\0" . '%d чарнавікоў захавана, пакуль не апублікаваны','%d needs fixing and stays a draft'=>'%d патрабуе выпраўлення і застаецца чарнавіком' . "\0" . '%d патрабуюць выпраўлення і застаюцца чарнавікамі' . "\0" . '%d патрабуюць выпраўлення і застаюцца чарнавікамі','Discard %d draft? Your live translations stay as they are.'=>'Адхіліць %d чарнавік? Вашы апублікаваныя пераклады застануцца без змен.' . "\0" . 'Адхіліць %d чарнавікі? Вашы апублікаваныя пераклады застануцца без змен.' . "\0" . 'Адхіліць %d чарнавікоў? Вашы апублікаваныя пераклады застануцца без змен.','%s (theme)'=>'%s (тэма)','Plugin or theme'=>'Плагін або тэма','Discard drafts…'=>'Адхіліць чарнавікі…','Show strings'=>'Паказаць радкі','Text, context, notes or file name'=>'Тэкст, кантэкст, нататкі або назва файла','Searches the original text, the translation, the context, notes for translators and the file the string comes from.'=>'Шукае ў арыгінальным Тэкст, перакладзе, кантэксце, нататках для перакладчыкаў і файле, з якога паходзіць радок.','Sort'=>'Сартаванне','Default'=>'Па змаўчанні','Untranslated first'=>'Спачатку неперакладзеныя','Recently edited'=>'Нядаўна адрэдагаваныя','A–Z'=>'А–Я','Source'=>'Крыніца','All sources'=>'Усе крыніцы','Original'=>'Арыгінал','Edit the selected string'=>'Рэдагаваць выбраны радок','Details and history'=>'Падрабязнасці і гісторыя','Edited by you'=>'Адрэдагавана вамі','Form %1$d: %2$s'=>'Форма %1$d: %2$s','Translation (%s)'=>'Пераклад (%s)','This language uses one form for every number.'=>'Гэтая мова выкарыстоўвае адну форму для ўсіх лікаў.','Plural forms'=>'Формы множнага ліку','empty'=>'пуста','problem'=>'праблема','Original (singular)'=>'Арыгінал (адзіночны лік)','Original (plural)'=>'Арыгінал (множны лік)','Copy original'=>'Скапіраваць арыгінал','Details'=>'Падрабязнасці','History'=>'Гісторыя','WordPress.org language pack'=>'Моўны пакет WordPress.org','Bundled with the plugin or theme'=>'Пастаўляецца разам з плагінам або тэмай','Yours (edited by you)'=>'Ваш (адрэдагаваны вамі)','Found in'=>'Знойдзена ў','Restore'=>'Аднавіць','Live'=>'Апублікавана','Draft'=>'Чарнавік','Draft · Problem'=>'Чарнавік · Праблема','Bundled'=>'У камплекце','Yours'=>'Ваш','(plural)'=>'(множны лік)','Discard this draft'=>'Адхіліць гэты чарнавік','Drafts discarded.'=>'Чарнавікі адхілены.','Draft discarded.'=>'Чарнавік адхілены.','This draft is kept, but it does not go live with Save until it is fixed. Your other changes still go live.'=>'Гэты чарнавік захаваны, але не будзе апублікаваны пры захаванні, пакуль не будзе выпраўлены. Іншыя вашы змены будуць апублікаваны.','Draft saved at %s. Not live yet.'=>'Чарнавік захаваны ў %s. Яшчэ не апублікаваны.','Visitors still see the live text until you press Save.'=>'Наведвальнікі працягваюць бачыць апублікаваны тэкст, пакуль вы не націснеце «Захаваць».','Live now: %1$s (%2$s)'=>'Зараз апублікавана: %1$s (%2$s)','Ctrl'=>'Ctrl','Enter'=>'Enter','next string'=>'наступны радок','previous / next'=>'папярэдні / наступны','copy original'=>'скапіраваць арыгінал','clear'=>'ачысціць','Open'=>'Адкрыць','Babilim – Auto Translation & Language Packs'=>'Babilim – аўтаматычны пераклад і моўныя пакеты','Auto-translate every plugin and theme on your site, then fine-tune any line in a fast built-in editor. Your edits survive updates.'=>'Аўтаматычна перакладайце кожны плагін і тэму на сайце, а потым дапрацоўвайце любы радок у хуткім убудаваным рэдактары. Вашы праўкі захоўваюцца пры абнаўленнях.','%d change to review'=>'%d змена для праверкі' . "\0" . '%d змены для праверкі' . "\0" . '%d змен для праверкі','No translation yet'=>'Перакладу яшчэ няма','The original text changed in %1$s %2$s.'=>'Арыгінальны тэкст змяніўся ў %1$s %2$s.','Your translation was written for the old text, so the site no longer shows it. Choose what to use for the new text.'=>'Ваш пераклад быў напісаны для старога тэксту, таму сайт больш яго не паказвае. Выберыце, што выкарыстоўваць для новага тэксту.','Old original'=>'Стары арыгінал','New original'=>'Новы арыгінал','Your translation (for the old text)'=>'Ваш пераклад (для старога тэксту)','Your current translation'=>'Ваш бягучы пераклад','Use my text'=>'Выкарыстаць мой тэкст','New translation from %s'=>'Новы пераклад ад %s','Use the new translation'=>'Выкарыстаць новы пераклад','Keep my current translation'=>'Захаваць мой бягучы пераклад','Discard my text'=>'Адхіліць мой тэкст','Whichever you choose becomes a draft and goes live with Save, like any other change.'=>'Любы выбар стане чарнавіком і будзе апублікаваны пры захаванні, як і любая іншая змена.','Or edit it yourself'=>'Або адрэдагуйце самі','This text is no longer used: %1$s %2$s does not have this string any more.'=>'Гэты тэкст больш не выкарыстоўваецца: у %1$s %2$s гэтага радка больш няма.','Delete…'=>'Выдаліць…','Delete your translation of this text? It is not shown anywhere on the site.'=>'Выдаліць ваш пераклад гэтага тэксту? Ён нідзе не паказваецца на сайце.','Translation deleted.'=>'Пераклад выдалены.','That text is still in use, so it cannot be removed here.'=>'Гэты тэкст усё яшчэ выкарыстоўваецца, таму яго нельга выдаліць тут.','%1$s – %2$s'=>'%1$s – %2$s','Removed text:'=>'Выдалены тэкст:','Added text:'=>'Дададзены тэкст:','When something fails inside Babilim, send an error report to the Babilim service: what failed, where and when, a random report ID, the versions and the site language. Only the error, where it happened and the versions are published as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Калі ў Babilim нешта збоіць, адпраўляць справаздачу пра памылку ў сервіс Babilim: што збойвала, дзе і калі, выпадковы ідэнтыфікатар справаздачы, версіі і мова сайта. Як публічная праблема на GitHub публікуюцца толькі памылка, месца яе ўзнікнення і версіі; публічная праблема не змяшчае адраса сайта, кантэнту або шляхоў да файлаў. Па змаўчанні выключана.','Translation edits'=>'Правкі перакладаў','Share my edits with Babilim'=>'Падзяліцца маімі праўкамі з Babilim','When you change a translation that came from Babilim, your version is sent with the original text, Babilim\'s translation, the plugin or theme, the language and the build. Babilim processes it with AI models and may use it to improve that translation for every site. Off by default.'=>'Калі вы змяняеце пераклад, атрыманы ад Babilim, ваша версія адпраўляецца разам з зыходным тэкстам, перакладам Babilim, плагінам або тэмай, мовай і зборкай. Babilim апрацоўвае яе з дапамогай мадэляў AI і можа выкарыстоўваць яе, каб палепшыць гэты пераклад для ўсіх сайтаў. Па змаўчанні выключана.','Your own translations'=>'Вашы ўласныя пераклады','Keep my translations when removing everything or uninstalling Babilim.'=>'Захаваць мае пераклады пры выдаленні ўсяго або выдаленні Babilim.','Your edits and the files you put in %s always take priority over Babilim\'s. Unchecking this deletes them when you remove everything or uninstall.'=>'Вашы праўкі і файлы, якія вы змясціце ў %s, заўсёды маюць прыярытэт над перакладамі Babilim. Калі зняць гэты сцяжок, яны будуць выдалены пры выдаленні ўсяго або выдаленні плагіна.','Files: %s.'=>'Файлы: %s.','Imported: %s.'=>'Імпартавана: %s.','Already identical: %s.'=>'Ужо ідэнтычныя: %s.','Kept your existing translation: %s.'=>'Захаваны ваш існуючы пераклад: %s.','Imported, but no longer used in this version: %s.'=>'Імпартавана, але больш не выкарыстоўваецца ў гэтай версіі: %s.','Kept as drafts to fix: %s.'=>'Захавана як чарнавікі для выпраўлення: %s.','Skipped: %s.'=>'Прапушчана: %s.','Review the import'=>'Праверыць імпарт','Loco Translate\'s files are not changed. Deactivate Loco Translate yourself when you are ready.'=>'Файлы Loco Translate не змяняюцца. Дэактывуйце Loco Translate самі, калі будзеце гатовыя.','Import from Loco Translate'=>'Імпарт з Loco Translate','Found %s Loco Translate file you can import.'=>'Знойдзены %s файл Loco Translate, які можна імпартаваць.' . "\0" . 'Знойдзена %s файлы Loco Translate, якія можна імпартаваць.' . "\0" . 'Знойдзена %s файлаў Loco Translate, якія можна імпартаваць.','Get the text list from Babilim'=>'Атрымаць спіс тэкстаў ад Babilim','Sends the plugin\'s or theme\'s name and version to Babilim.'=>'Адпраўляе ў Babilim назву і версію плагіна або тэмы.','Babilim is preparing the list. This takes a few minutes.'=>'Babilim рыхтуе спіс. Гэта зойме некалькі хвілін.','Enable Babilim to get the text list for this plugin or theme.'=>'Уключыце Babilim, каб атрымаць спіс тэкстаў для гэтага плагіна або тэмы.','Babilim cannot list the text of this plugin or theme: it is not on WordPress.org and it ships no translation template.'=>'Babilim не можа скласці спіс тэкстаў гэтага плагіна або тэмы: яго няма на WordPress.org, і ён не ўтрымлівае шаблон перакладу.','Babilim found no translatable text in this version.'=>'Babilim не знайшоў тэксту для перакладу ў гэтай версіі.','The editor session has expired.'=>'Сеанс рэдактара скончыўся.','That plugin or theme is not available here.'=>'Гэты плагін або тэма тут недаступныя.','Some Loco Translate files could not be read.'=>'Не ўдалося прачытаць некаторыя файлы Loco Translate.','This plugin or theme is not on WordPress.org.'=>'Гэтага плагіна або тэмы няма на WordPress.org.','Babilim returned an invalid text list.'=>'Babilim вярнуў няправільны спіс тэкстаў.','The text list could not be saved.'=>'Не ўдалося захаваць спіс тэкстаў.']];